// @/components/SozlukEkrani.tsx
import React, { useState, useEffect, useMemo, useRef, useCallback } from "react";
import Header from "@/components/Header";
import SearchBox from "@/components/SearchBox";
import KelimeKarti from "@/components/KelimeKarti";
import GununKelimesiKart from "@/components/GununKelimesiKart";
import KelimeDetayDrawer from "@/components/KelimeDetayDrawer";
import { AramaModu, GruplanmisKelime } from "@/types/dictionary";

export default function SozlukEkrani(dict: any) { // Tip tanımları buraya eklenecek
  const [metinBoyutu, setMetinBoyutu] = useState<number>(16);
  const [karanlikMod, setKaranlikMod] = useState<boolean>(false);
  const [mod, setMod] = useState<AramaModu>("baslayan");
  const [hedefDil, setHedefDil] = useState<string>("tumu");
  const [goruntulenenAdet, setGoruntulenenAdet] = useState<number>(20);
  const [seciliKelimeGrubu, setSeciliKelimeGrubu] = useState<GruplanmisKelime | null>(null);
  const [kopyalandiId, setKopyalandiId] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (karanlikMod) document.documentElement.classList.add("dark");
    else document.documentElement.classList.remove("dark");
  }, [karanlikMod]);

  const aktifTema = useMemo(() => ({
    arkaPlan: karanlikMod ? "#0c0f17" : "#f8fafc",
    kartArkaPlan: karanlikMod ? "#141a29" : "#ffffff",
    yaziAna: karanlikMod ? "#f8fafc" : "#0f172a",
    yaziAlt: karanlikMod ? "#cbd5e1" : "#334155",
    kenarlik: karanlikMod ? "#334155" : "#cbd5e1",
    inputArkaPlan: karanlikMod ? "#1a2236" : "#ffffff",
  }), [karanlikMod]);

  const gruplanmisSonuclar = useMemo(() => {
    if (!dict.searchQuery?.trim() || !dict.filtrelenmisSonuclar) return [];
    const gruplar = new Map<string, any[]>();
    dict.filtrelenmisSonuclar.forEach((item: any) => {
      const key = item.kelime?.trim().toLowerCase();
      if (!key) return;
      if (!gruplar.has(key)) gruplar.set(key, []);
      gruplar.get(key)!.push(item);
    });
    return Array.from(gruplar.values()).map(kaynaklar => ({
      kelime: kaynaklar[0].kelime,
      dialect: kaynaklar[0].dialect,
      kaynaklar,
    }));
  }, [dict.filtrelenmisSonuclar, dict.searchQuery]);

  const handleKelimeSec = useCallback((grup: GruplanmisKelime) => setSeciliKelimeGrubu(grup), []);
  const gosterilenGruplar = gruplanmisSonuclar.slice(0, goruntulenenAdet);

  return (
    <div className="flex flex-col min-h-screen transition-colors px-4 py-6" style={{ backgroundColor: aktifTema.arkaPlan }}>
      <main className="flex-1 max-w-4xl w-full mx-auto space-y-6">
        <Header karanlikMod={karanlikMod} toggleKaranlikMod={() => setKaranlikMod(!karanlikMod)} metinBoyutu={metinBoyutu} setMetinBoyutu={setMetinBoyutu} tema={aktifTema} />
        
        {/* SearchBox, GununKelimesiKart bileşenleri prop iletme mantığı ile eklenecektir */}
        
        <section aria-label="Arama Sonuçları" className="flex flex-col gap-4">
          {gosterilenGruplar.map((grup) => (
            <KelimeKarti
              key={`${grup.kelime}-${grup.kaynaklar.length}`}
              idx={0}
              grup={grup}
              tema={aktifTema}
              metinBoyutu={metinBoyutu}
              kopyalandiId={kopyalandiId}
              panoyaKopyala={async () => {}} // Kopyalama mantığı helper içerisinden eklenecek
              onClick={handleKelimeSec}
            />
          ))}
        </section>

        {seciliKelimeGrubu && <KelimeDetayDrawer seciliKelime={seciliKelimeGrubu} kapat={() => setSeciliKelimeGrubu(null)} tema={aktifTema} metinBoyutu={metinBoyutu} />}
      </main>
    </div>
  );
}